contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, bool doRenounce) public {
        // Setup precondition: contract deployed by this test starts uninitialized; initialize it.
        // We must not require on c's state before creating it, so call initialize unconditionally.
        // initialize() can only be called once, and this run is the only transaction on fresh c.
        c.initialize();

        // Read current owner through public view (allowed).
        address initialOwner = c.owner();

        // If doRenounce is true, renounce ownership (top-level call).
        if (doRenounce) {
            c.renounceOwnership();
        } else {
            // Otherwise, transfer ownership to newOwner if nonzero, to set up a non-renounced scenario.
            if (newOwner != address(0)) {
                c.transferOwnership(newOwner);
            }
        }

        // Final owner after all state-changing calls.
        address finalOwner = c.owner();

        // General rule: after a successful renounceOwnership, owner is zero; otherwise owner is nonzero.
        if (doRenounce) {
            assert(finalOwner == address(0));
        } else {
            assert(finalOwner != address(0));
        }
    }
}

