contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address ownerBefore = c.owner();
        bool callerIsOwner = (ownerBefore == address(this));
        bool newOwnerIsZero = (newOwner == address(0));

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldRevert = !callerIsOwner || newOwnerIsZero;
        address ownerAfter = c.owner();

        assert(
            reverted == shouldRevert &&
            (reverted ? ownerAfter == ownerBefore : ownerAfter == newOwner)
        );
    }

    receive() external payable {}
}

