contract InvMutTest {
    C c;

    event AlloSettingsUpdated(address alloSettings);

    constructor(C _c) {
        c = _c;
    }

    function run(address newAlloSettings) public {
        // Read the value before the state-changing call
        address before = c.alloSettings();

        // Drive the public entry point
        c.updateAlloSettings(newAlloSettings);

        // The rule: after the update, the public state variable equals the new value.
        // This must hold for every input, regardless of the previous value.
        assert(c.alloSettings() == newAlloSettings);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newAlloSettings) public {
        // The contract starts with no owner, so updateAlloSettings will revert.
        // We cannot bypass onlyOwner from this test contract directly.
        // Therefore, the rule must be expressed conditionally: IF the call succeeds,
        // THEN the state variable equals the argument.
        bool reverted;
        try c.updateAlloSettings(newAlloSettings) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the call did not revert, the state must be updated.
        // If it reverted, we don't assert anything about the state change.
        if (!reverted) {
            assert(c.alloSettings() == newAlloSettings);
        }
    }

    receive() external payable {}
}
